const shape = new THREE.Shape();
const R = 3.05;
const outerCenterY = -1.55;
const innerCenterY = -2.05;
const startAngleOuter = Math.atan2(0.55, 3);
const endAngleOuter = Math.atan2(0.55, -3);
shape.absarc(0, outerCenterY, R, startAngleOuter, endAngleOuter, false);
shape.lineTo(-3, -1.5);
const startAngleInner = Math.atan2(0.55, -3);
const endAngleInner = Math.atan2(0.55, 3);
shape.absarc(0, innerCenterY, R, startAngleInner, endAngleInner, true);
shape.lineTo(3, -1.0);
const extrudeSettings = { depth: height, bevelEnabled: false, curveSegments: 64 };
const geom = new THREE.ExtrudeGeometry(shape, extrudeSettings);
geom.rotateX(-Math.PI / 2);
geom.translate(0, -height/2, 0);
return geom;

const group = new THREE.Group();

// Back sofa
const backGeo = new THREE.BoxGeometry(width, height, depth * 0.2);
const backMesh = new THREE.Mesh(backGeo);
backMesh.position.set(0, 0, -depth * 0.4);
group.add(backMesh);

// Left sofa
const leftGeo = new THREE.BoxGeometry(width * 0.2, height * 0.6, depth * 0.8);
const leftMesh = new THREE.Mesh(leftGeo);
leftMesh.position.set(-width * 0.4, -height * 0.2, depth * 0.1);
group.add(leftMesh);

// Right sofa
const rightGeo = new THREE.BoxGeometry(width * 0.2, height * 0.6, depth * 0.8);
const rightMesh = new THREE.Mesh(rightGeo);
rightMesh.position.set(width * 0.4, -height * 0.2, depth * 0.1);
group.add(rightMesh);

// Coffee table
const tableGeo = new THREE.BoxGeometry(width * 0.5, height * 0.3, depth * 0.5);
const tableMesh = new THREE.Mesh(tableGeo);
tableMesh.position.set(0, -height * 0.35, depth * 0.1);
group.add(tableMesh);

return group;

const group = new THREE.Group();
const count = 5;
const spacing = width / count;
const lWidth = spacing * 0.8;
const lDepth = depth;
const bHeight = height * 0.4;
const cThickness = height * 0.2;

const woodMat = new THREE.MeshStandardMaterial({color: 0x8b5a2b, roughness: 0.8});
const clothMat = new THREE.MeshStandardMaterial({color: 0xf0f0f0, roughness: 0.9});

for(let i=0; i<count; i++) {
    const x = -width/2 + spacing/2 + i*spacing;

    const baseGeo = new THREE.BoxGeometry(lWidth, bHeight, lDepth);
    const base = new THREE.Mesh(baseGeo, woodMat);
    base.position.set(x, -height/2 + bHeight/2, 0);
    group.add(base);

    const seatDepth = lDepth * 0.6;
    const seatGeo = new THREE.BoxGeometry(lWidth*0.9, cThickness, seatDepth);
    const seat = new THREE.Mesh(seatGeo, clothMat);
    seat.position.set(x, -height/2 + bHeight + cThickness/2, -lDepth/2 + seatDepth/2);
    group.add(seat);

    const backHeight = (height - bHeight) / Math.cos(Math.PI/6);
    const backGeo = new THREE.BoxGeometry(lWidth*0.9, backHeight, cThickness);
    const back = new THREE.Mesh(backGeo, clothMat);
    back.position.set(x, -height/2 + bHeight + (height - bHeight)/2, seat.position.z + seatDepth/2 + (backHeight/2)*Math.sin(Math.PI/6));
    back.rotation.x = Math.PI / 6;
    group.add(back);
}
return group;

